180	  const units = textUnits(label);
181	  return {
182	    width: Math.max(42, Math.min(168, Math.round(units * 7.1 + 18))),
183	    height: units > 22 ? 34 : 20,
184	  };
185	}
186	
187	function routeMidpoint(points: Array<{ x: number; y: number }>) {
188	  if (points.length < 2) return undefined;
189	  const segments = points.slice(0, -1).map((start, index) => ({
190	    start,
191	    end: points[index + 1],
192	    length: Math.abs(points[index + 1].x - start.x) + Math.abs(points[index + 1].y - start.y),
193	  }));
194	  const total = segments.reduce((sum, segment) => sum + segment.length, 0);
195	  let remaining = total / 2;
196	  for (const segment of segments) {
197	    if (remaining > segment.length) {
198	      remaining -= segment.length;
199	      continue;
200	    }
201	    const ratio = segment.length === 0 ? 0 : remaining / segment.length;
202	    return {
203	      x: segment.start.x + (segment.end.x - segment.start.x) * ratio,
204	      y: segment.start.y + (segment.end.y - segment.start.y) * ratio,
205	    };
206	  }
207	  return points[Math.floor(points.length / 2)];
208	}
209	
210	function rotateSide(side: SemanticPortSide | undefined, fallback: SemanticPortSide, orientation: LayoutOrientation): SemanticPortSide {
211	  const resolved = side ?? fallback;
212	  if (orientation === "RIGHT") return resolved;
213	  if (resolved === "left") return "top";
214	  if (resolved === "right") return "bottom";
215	  if (resolved === "top") return "left";
216	  return "right";
217	}
218	
219	function routeSides(relationship: SemanticRelationship, orientation: LayoutOrientation) {
220	  return {
221	    sourceSide: rotateSide(relationship.layoutHints?.sourcePortSide, "right", orientation),
222	    targetSide: rotateSide(relationship.layoutHints?.targetPortSide, "left", orientation),
223	  };
224	}
225	
226	function stableObjectOrder(graph: SemanticGraph, previous?: CanvasLayout) {
227	  const result = new Map<string, number>();
228	  const byRegion = new Map<string, typeof graph.objects>();
229	  for (const object of graph.objects) byRegion.set(object.regionId, [...(byRegion.get(object.regionId) ?? []), object]);
230	  for (const objects of byRegion.values()) {
231	    objects.sort((left, right) => {
232	      const leftRect = previous?.objectRects[left.id];
233	      const rightRect = previous?.objectRects[right.id];
234	      if (leftRect && rightRect) {
235	        const primary = previous?.orientation === "DOWN" ? leftRect.x - rightRect.x : leftRect.y - rightRect.y;
236	        if (primary !== 0) return primary;
237	      }
238	      if (leftRect && !rightRect) return -1;
239	      if (!leftRect && rightRect) return 1;
240	      return (left.layoutHints?.order ?? 0) - (right.layoutHints?.order ?? 0) || left.id.localeCompare(right.id);
241	    });
242	    objects.forEach((object, index) => result.set(object.id, index));
243	  }
244	  return result;
245	}
246	
247	function buildPortSpecs(graph: SemanticGraph, orientation: LayoutOrientation) {
248	  const portsByObject = new Map<string, PortSpec[]>();
249	  const relationshipPorts = new Map<string, { sourcePortId: string; targetPortId: string; sourceSide: SemanticPortSide; targetSide: SemanticPortSide }>();
250	  const orderedRelationships = [...graph.relationships].sort((left, right) =>
251	    (left.layoutHints?.order ?? 0) - (right.layoutHints?.order ?? 0) || left.id.localeCompare(right.id));
252	  const sideCounts = new Map<string, number>();
253	
254	  for (const relationship of orderedRelationships) {
255	    const { sourceSide, targetSide } = routeSides(relationship, orientation);
256	    const sourceKey = `${relationship.sourceObjectId}:${sourceSide}`;
257	    const targetKey = `${relationship.targetObjectId}:${targetSide}`;
258	    const sourceOrder = sideCounts.get(sourceKey) ?? 0;
259	    const targetOrder = sideCounts.get(targetKey) ?? 0;
260	    sideCounts.set(sourceKey, sourceOrder + 1);
261	    sideCounts.set(targetKey, targetOrder + 1);
262	    const sourcePortId = `${relationship.id}:source-port`;
263	    const targetPortId = `${relationship.id}:target-port`;
264	    portsByObject.set(relationship.sourceObjectId, [
265	      ...(portsByObject.get(relationship.sourceObjectId) ?? []),
266	      { id: sourcePortId, side: sourceSide, order: sourceOrder },
267	    ]);
268	    portsByObject.set(relationship.targetObjectId, [
269	      ...(portsByObject.get(relationship.targetObjectId) ?? []),
270	      { id: targetPortId, side: targetSide, order: targetOrder },
271	    ]);
272	    relationshipPorts.set(relationship.id, { sourcePortId, targetPortId, sourceSide, targetSide });
273	  }
274	  return { portsByObject, relationshipPorts };
275	}
276	
277	function regionDepth(region: SemanticRegion, regionById: Map<string, SemanticRegion>) {
278	  let depth = 0;
279	  let cursor = region.parentRegionId ? regionById.get(region.parentRegionId) : undefined;
280	  const seen = new Set<string>();
281	  while (cursor && !seen.has(cursor.id)) {
282	    depth += 1;
283	    seen.add(cursor.id);
284	    cursor = cursor.parentRegionId ? regionById.get(cursor.parentRegionId) : undefined;
285	  }
286	  return depth;
287	}
288	
289	function asElkPort(port: PortSpec): ElkPort {
290	  return {
291	    id: port.id,
292	    width: 2,
293	    height: 2,
294	    layoutOptions: {
295	      "elk.port.side": SIDE_TO_ELK[port.side],
296	      "elk.port.index": String(port.order),
297	    },
298	  };
299	}
300	
301	function regionOptions(orientation: LayoutOrientation, depth: number) {
302	  return {
303	    "elk.algorithm": "layered",
304	    "elk.direction": orientation,
305	    "elk.edgeRouting": "ORTHOGONAL",
306	    "elk.padding": `[top=${depth === 0 ? 54 : 46},left=26,bottom=26,right=26]`,
307	    "elk.spacing.nodeNode": depth === 0 ? "34" : "28",
308	    "elk.layered.spacing.nodeNodeBetweenLayers": depth === 0 ? "82" : "68",
309	    "elk.layered.spacing.edgeNodeBetweenLayers": "30",
310	    "elk.layered.spacing.edgeEdgeBetweenLayers": "16",
311	    "elk.layered.nodePlacement.strategy": "NETWORK_SIMPLEX",
312	    "elk.layered.crossingMinimization.strategy": "LAYER_SWEEP",
313	    "elk.layered.crossingMinimization.greedySwitch.type": "TWO_SIDED",
314	  };
315	}
316	
317	export async function layoutSemanticGraph(
318	  graph: SemanticGraph,
319	  options: { orientation?: LayoutOrientation; previousLayout?: CanvasLayout } = {},
320	): Promise<CanvasLayout> {
321	  const started = typeof performance === "undefined" ? Date.now() : performance.now();
322	  const fingerprint = semanticGraphFingerprint(graph);
323	  if (options.previousLayout?.fingerprint === fingerprint) return { ...options.previousLayout, graphId: graph.id, fingerprint, durationMs: 0 };
324	  const orientation = options.orientation ?? "RIGHT";
325	  const objectOrder = stableObjectOrder(graph, options.previousLayout);
326	  const { portsByObject, relationshipPorts } = buildPortSpecs(graph, orientation);
327	  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
328	  const objectsByRegion = new Map<string, typeof graph.objects>();
329	  const childRegions = new Map<string | null, SemanticRegion[]>();
330	  for (const object of graph.objects) objectsByRegion.set(object.regionId, [...(objectsByRegion.get(object.regionId) ?? []), object]);
331	  for (const region of graph.regions) childRegions.set(region.parentRegionId ?? null, [...(childRegions.get(region.parentRegionId ?? null) ?? []), region]);
332	
333	  const buildRegion = (region: SemanticRegion): ElkNode => {
334	    const depth = regionDepth(region, regionById);
335	    const nestedRegions = [...(childRegions.get(region.id) ?? [])]
336	      .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id))
337	      .map(buildRegion);
338	    const objects = [...(objectsByRegion.get(region.id) ?? [])]
339	      .sort((left, right) => (objectOrder.get(left.id) ?? 0) - (objectOrder.get(right.id) ?? 0) || left.id.localeCompare(right.id))
340	      .map<ElkNode>((object) => {
341	        const size = objectSize(object.name, object.summary);
342	        return {
343	          id: object.id,
344	          width: size.width,
345	          height: size.height,
346	          ports: (portsByObject.get(object.id) ?? []).sort((left, right) => left.side.localeCompare(right.side) || left.order - right.order).map(asElkPort),
347	          layoutOptions: {
348	            "elk.portConstraints": "FIXED_ORDER",
349	            "elk.layered.priority.direction": String(Math.round(object.importance.score)),
350	          },
351	        };
352	      });
353	    return {
354	      id: region.id,
355	      children: [...nestedRegions, ...objects],
356	      layoutOptions: regionOptions(orientation, depth),
357	    };
358	  };
359	
360	  const rootChildren = [...(childRegions.get(null) ?? [])]
361	    .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id))
362	    .map(buildRegion);
363	  const elkEdges: ElkEdge[] = graph.relationships.map((relationship) => {
364	    const ports = relationshipPorts.get(relationship.id);
365	    const label = relationship.label?.trim();
366	    const flowIds = Array.isArray(relationship.metadata.flowIds) ? relationship.metadata.flowIds : [];
367	    const includeLabelInLayout = graph.objects.length <= 60 || flowIds.length > 0;
368	    const labelSize = label && includeLabelInLayout ? edgeLabelSize(label) : null;
369	    return {
370	      id: relationship.id,
371	      sources: [ports?.sourcePortId ?? relationship.sourceObjectId],
372	      targets: [ports?.targetPortId ?? relationship.targetObjectId],
373	      labels: label && labelSize ? [{ id: `${relationship.id}:label`, text: label, ...labelSize }] : [],
374	    };
375	  });
376	
377	  const output = await elk.layout({
378	    id: graph.id,
379	    layoutOptions: {
380	      ...regionOptions(orientation, -1),
381	      "elk.hierarchyHandling": "INCLUDE_CHILDREN",
382	      "elk.separateConnectedComponents": "false",
383	      "elk.spacing.componentComponent": "72",
384	      "elk.spacing.edgeNode": "28",
385	      "elk.spacing.labelNode": "18",
386	      "elk.spacing.edgeLabel": "12",
387	      "elk.edgeLabels.inline": "true",
388	      "elk.layered.unnecessaryBendpoints": "true",
389	      "elk.layered.thoroughness": graph.objects.length >= 80 ? "3" : "7",
390	      "elk.padding": "[top=42,left=42,bottom=42,right=42]",
391	    },
392	    children: rootChildren,
393	    edges: elkEdges,
394	  } as unknown as Parameters<typeof elk.layout>[0]) as unknown as ElkNode;
395	
396	  const objectRects: Record<string, LayoutRect> = {};
397	  const regionRects: Record<string, RegionLayoutRect> = {};
398	  const absoluteOffsetById = new Map<string, { x: number; y: number }>([[graph.id, { x: 0, y: 0 }]]);
399	  const objectIds = new Set(graph.objects.map((object) => object.id));
400	  const regionIds = new Set(graph.regions.map((region) => region.id));
401	
402	  const visit = (node: ElkNode, parentOffset: { x: number; y: number }) => {
403	    const x = parentOffset.x + (node.x ?? 0);
404	    const y = parentOffset.y + (node.y ?? 0);
405	    absoluteOffsetById.set(node.id, { x, y });
406	    if (objectIds.has(node.id)) objectRects[node.id] = { id: node.id, x, y, width: node.width ?? 0, height: node.height ?? 0 };
407	    if (regionIds.has(node.id)) {
408	      const region = regionById.get(node.id)!;
409	      regionRects[node.id] = {
410	        id: node.id,
411	        x,
412	        y,
413	        width: node.width ?? 0,
414	        height: node.height ?? 0,
415	        depth: regionDepth(region, regionById),
416	        parentRegionId: region.parentRegionId,
417	      };
418	    }
419	    for (const child of node.children ?? []) visit(child, { x, y });
420	  };
421	  visit(output, { x: 0, y: 0 });
422	
423	  const outputEdges: ElkEdge[] = [];
424	  const collectEdges = (node: ElkNode) => {
425	    outputEdges.push(...(node.edges ?? []));
426	    for (const child of node.children ?? []) collectEdges(child);
427	  };
428	  collectEdges(output);
429	
430	  const relationshipRoutes: Record<string, RelationshipRoute> = {};
431	  for (const edge of outputEdges) {
432	    const relationship = graph.relationships.find((candidate) => candidate.id === edge.id);
433	    if (!relationship) continue;
434	    const ports = relationshipPorts.get(edge.id);
435	    const offset = absoluteOffsetById.get(edge.container ?? graph.id) ?? { x: 0, y: 0 };
436	    const points: Array<{ x: number; y: number }> = [];
437	    for (const section of edge.sections ?? []) {
438	      const sectionPoints = [section.startPoint, ...(section.bendPoints ?? []), section.endPoint]
439	        .filter((point): point is ElkPoint => Boolean(point))
440	        .map((point) => ({ x: offset.x + (point.x ?? 0), y: offset.y + (point.y ?? 0) }));
441	      if (points.length > 0 && sectionPoints.length > 0) {
442	        const previous = points.at(-1)!;
443	        const next = sectionPoints[0];
444	        if (previous.x === next.x && previous.y === next.y) sectionPoints.shift();
445	      }
446	      points.push(...sectionPoints);
447	    }
448	    const label = edge.labels?.[0];
449	    relationshipRoutes[edge.id] = {
450	      id: edge.id,
451	      points,
452	      labelPoint: label
453	        ? { x: offset.x + (label.x ?? 0) + label.width / 2, y: offset.y + (label.y ?? 0) + label.height / 2 }
454	        : routeMidpoint(points),
455	      sourceSide: ports?.sourceSide ?? "right",
456	      targetSide: ports?.targetSide ?? "left",
457	    };
458	  }
459	
460	  const finished = typeof performance === "undefined" ? Date.now() : performance.now();
461	  const result: CanvasLayout = {
462	    graphId: graph.id,
463	    fingerprint,
464	    orientation,
465	    width: output.width ?? 0,
466	    height: output.height ?? 0,
467	    durationMs: Math.round((finished - started) * 100) / 100,
468	    objectRects,
469	    regionRects,
470	    relationshipRoutes,
471	  };
472	  return options.previousLayout ? stabilizeIncrementalLayout(graph, options.previousLayout, result) : result;
473	}
474	
475	export function measureLayoutStability(previous: CanvasLayout, next: CanvasLayout) {
476	  const commonObjectIds = Object.keys(previous.objectRects).filter((id) => next.objectRects[id]);
477	  if (commonObjectIds.length < 2) return { commonObjects: commonObjectIds.length, relativeOrderRetention: 1, meanDisplacement: 0 };
478	  const previousOrder = [...commonObjectIds].sort((left, right) => {
479	    const leftRect = previous.objectRects[left];
480	    const rightRect = previous.objectRects[right];
481	    return previous.orientation === "DOWN" ? leftRect.x - rightRect.x : leftRect.y - rightRect.y;
482	  });
483	  const nextOrder = new Map([...commonObjectIds].sort((left, right) => {
484	    const leftRect = next.objectRects[left];
485	    const rightRect = next.objectRects[right];
486	    return next.orientation === "DOWN" ? leftRect.x - rightRect.x : leftRect.y - rightRect.y;
487	  }).map((id, index) => [id, index]));
488	  let inversions = 0;
489	  let pairs = 0;
490	  for (let leftIndex = 0; leftIndex < previousOrder.length; leftIndex += 1) {
491	    for (let rightIndex = leftIndex + 1; rightIndex < previousOrder.length; rightIndex += 1) {
492	      pairs += 1;
493	      if ((nextOrder.get(previousOrder[leftIndex]) ?? 0) > (nextOrder.get(previousOrder[rightIndex]) ?? 0)) inversions += 1;
494	    }
495	  }
496	  const anchorId = commonObjectIds[0];
497	  const anchorDelta = {
498	    x: next.objectRects[anchorId].x - previous.objectRects[anchorId].x,
499	    y: next.objectRects[anchorId].y - previous.objectRects[anchorId].y,
500	  };
501	  const meanDisplacement = commonObjectIds.reduce((total, id) => {
502	    const previousRect = previous.objectRects[id];
503	    const nextRect = next.objectRects[id];
504	    return total + Math.hypot(nextRect.x - previousRect.x - anchorDelta.x, nextRect.y - previousRect.y - anchorDelta.y);
505	  }, 0) / commonObjectIds.length;
506	  return {
507	    commonObjects: commonObjectIds.length,
508	    relativeOrderRetention: pairs === 0 ? 1 : Math.round((1 - inversions / pairs) * 1000) / 1000,
509	    meanDisplacement: Math.round(meanDisplacement * 100) / 100,
510	  };
511	}
