import {
  indexSemanticGraph,
  type SemanticFlow,
  type SemanticGraph,
  type SemanticObject,
  type SemanticRegion,
  type SemanticRelationship,
  type SemanticState,
} from "./semantic-graph";
import type { CanvasSelection } from "./interaction";

type InspectorBase = {
  id: string;
  title: string;
  typeLabel: string;
  summary: string;
  state: SemanticState;
  location: string;
  raw: Record<string, unknown>;
};

export type ObjectInspectorBinding = InspectorBase & {
  kind: "object";
  object: SemanticObject;
  region?: SemanticRegion;
  incoming: SemanticRelationship[];
  outgoing: SemanticRelationship[];
  flows: SemanticFlow[];
};

export type RelationshipInspectorBinding = InspectorBase & {
  kind: "relationship";
  relationship: SemanticRelationship;
  source?: SemanticObject;
  target?: SemanticObject;
  flows: SemanticFlow[];
};

export type FlowInspectorBinding = InspectorBase & {
  kind: "flow";
  flow: SemanticFlow;
  objects: SemanticObject[];
  relationships: SemanticRelationship[];
};

export type InspectorBinding = ObjectInspectorBinding | RelationshipInspectorBinding | FlowInspectorBinding;

export function bindInspector(graph: SemanticGraph, selection: CanvasSelection): InspectorBinding | null {
  if (!selection) return null;
  const index = indexSemanticGraph(graph);
  if (selection.kind === "object") {
    const object = index.objectById.get(selection.id);
    if (!object) return null;
    const region = index.regionById.get(object.regionId);
    const incoming = index.incomingByObjectId.get(object.id) ?? [];
    const outgoing = index.outgoingByObjectId.get(object.id) ?? [];
    const flows = graph.flows.filter((flow) => flow.objectIds.includes(object.id));
    return {
      kind: "object",
      id: object.id,
      title: object.name,
      typeLabel: object.objectType,
      summary: object.summary || "尚无概述。",
      state: object.state,
      location: region?.name ?? "Unscoped",
      raw: { ...object.metadata, importance: object.importance, layoutHints: object.layoutHints },
      object,
      region,
      incoming,
      outgoing,
      flows,
    };
  }
  if (selection.kind === "relationship") {
    const relationship = index.relationshipById.get(selection.id);
    if (!relationship) return null;
    const source = index.objectById.get(relationship.sourceObjectId);
    const target = index.objectById.get(relationship.targetObjectId);
    const flows = graph.flows.filter((flow) => flow.relationshipIds.includes(relationship.id));
    return {
      kind: "relationship",
      id: relationship.id,
      title: relationship.label || relationship.relationshipType,
      typeLabel: `${relationship.relationshipType} relationship`,
      summary: relationship.summary || `${source?.name ?? relationship.sourceObjectId} → ${target?.name ?? relationship.targetObjectId}`,
      state: relationship.state,
      location: `${source?.name ?? relationship.sourceObjectId} → ${target?.name ?? relationship.targetObjectId}`,
      raw: { ...relationship.metadata, direction: relationship.direction, importance: relationship.importance, layoutHints: relationship.layoutHints },
      relationship,
      source,
      target,
      flows,
    };
  }
  const flow = index.flowById.get(selection.id);
  if (!flow) return null;
  const objects = flow.objectIds.map((id) => index.objectById.get(id)).filter((object): object is SemanticObject => Boolean(object));
  const relationships = flow.relationshipIds.map((id) => index.relationshipById.get(id)).filter((relationship): relationship is SemanticRelationship => Boolean(relationship));
  const regionCount = new Set(objects.map((object) => object.regionId)).size;
  return {
    kind: "flow",
    id: flow.id,
    title: flow.name,
    typeLabel: "Flow",
    summary: flow.description || "Named system behavior.",
    state: flow.state,
    location: `${regionCount} region${regionCount === 1 ? "" : "s"}`,
    raw: { ...flow.metadata, importance: flow.importance, objectIds: flow.objectIds, relationshipIds: flow.relationshipIds },
    flow,
    objects,
    relationships,
  };
}

