"use client";

import Link from "next/link";
import { useCallback, useEffect, useState } from "react";
import ArchitectureCanvas from "../../architecture/architecture-canvas";
import type { ProjectRegistry } from "../../architecture/types";

export default function ProjectArchitecture({ projectId }: { projectId: string }) {
  const [registry, setRegistry] = useState<ProjectRegistry | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadProject = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const response = await fetch(`/api/projects?project_id=${encodeURIComponent(projectId)}`, { cache: "no-store" });
      if (!response.ok) throw new Error("PROJECT_UNAVAILABLE");
      setRegistry(await response.json() as ProjectRegistry);
    } catch {
      setError("这个 Project 暂时无法读取，可能尚未注册或 Registry 当前不可用。");
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  useEffect(() => {
    const timer = window.setTimeout(() => void loadProject(), 0);
    return () => window.clearTimeout(timer);
  }, [loadProject]);

  const detail = registry?.detail;
  const project = detail?.project;
  const activeChanges = detail?.changes.filter((change) => !["COMPLETED", "REJECTED"].includes(change.status.toUpperCase())).length ?? 0;

  return (
    <main className="architecture-page canvas-shell">
      <aside className="canvas-nav-rail" aria-label="Workspace navigation">
        <Link className="rail-brand" href="/" aria-label="Engineering Control Plane"><span aria-hidden="true"><i /><i /><i /></span></Link>
        <nav>
          <Link className="active" href={`/projects/${encodeURIComponent(projectId)}`} title="Architecture"><span aria-hidden="true">⌘</span><small>Map</small></Link>
          <Link href={`/maintenance?project=${encodeURIComponent(projectId)}&tab=overview`} title="Registry"><span aria-hidden="true">≡</span><small>Facts</small></Link>
        </nav>
        <button aria-label="Refresh project" disabled={loading} onClick={() => void loadProject()} title="Refresh" type="button">↻</button>
      </aside>

      <section className="canvas-workspace">
        <header className="canvas-contextbar">
          <div>
            <select
              aria-label="切换项目"
              disabled={!registry?.catalog.length}
              onChange={(event) => { window.location.href = `/projects/${encodeURIComponent(event.target.value)}`; }}
              value={project?.id ?? projectId}
            >
              {(registry?.catalog ?? []).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}
            </select>
            <span>Architecture Canvas</span>
          </div>
          <div>
            {activeChanges > 0 && <span className="change-live"><i />{activeChanges} active Change{activeChanges === 1 ? "" : "s"}</span>}
            <span className="context-revision">r{project?.revision ?? "—"}</span>
            <span className="context-readonly">Read model</span>
          </div>
        </header>

        {error && <section className="architecture-load-state error"><strong>读取失败</strong><p>{error}</p><button onClick={() => void loadProject()} type="button">重新读取</button></section>}
        {!error && loading && !detail && <section className="architecture-load-state"><span className="loading-pulse" /><strong>正在恢复项目认知…</strong><p>读取 Semantic Graph 与当前 Revision。</p></section>}
        {detail && <ArchitectureCanvas detail={detail} />}
      </section>
    </main>
  );
}

