1031	.inspector-heading { align-items: flex-start; border-bottom: 1px solid var(--map-line); display: flex; justify-content: space-between; padding: 15px 15px 13px; }
1032	.inspector-heading > div { display: grid; min-width: 0; }
1033	.inspector-heading small { color: var(--map-focus); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; letter-spacing: .08em; text-transform: uppercase; }
1034	.inspector-heading strong { font-size: .9375rem; line-height: 1.3; margin-top: 3px; overflow-wrap: anywhere; }
1035	.inspector-identity { border-bottom: 1px solid var(--map-line); padding: 14px 15px; }
1036	.inspector-identity > p { color: var(--map-text-soft); font-size: .8125rem; line-height: 1.6; }
1037	.inspector-identity dl { display: grid; margin: 12px 0 0; }
1038	.inspector-identity dl div, .inspector-facts div { border-top: 1px solid var(--map-line); display: grid; gap: 8px; grid-template-columns: 54px 1fr; padding: 7px 0; }
1039	.inspector-identity dt, .inspector-facts dt { color: var(--map-text-muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; }
1040	.inspector-identity dd, .inspector-facts dd { color: var(--map-text-soft); font-size: .8125rem; margin: 0; overflow-wrap: anywhere; }
1041	.inspector-identity dd { align-items: center; display: flex; gap: 5px; }
1042	.inspector-identity dd .severity-positive { color: #91b8ab; }
1043	.inspector-identity dd .severity-attention { color: var(--map-attention); }
1044	.inspector-identity dd .severity-critical { color: #d88982; }
1045	.inspector-focus-action { align-items: center; background: rgba(155,210,193,.08); border: 1px solid rgba(155,210,193,.3); color: var(--map-focus-strong); display: flex; font-size: .8125rem; justify-content: space-between; margin-top: 11px; min-height: 30px; padding: 4px 8px; width: 100%; }
1046	.inspector-focus-action span { border: 1px solid var(--map-line-strong); color: var(--map-text-muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; padding: 0 4px; }
1047	.canvas-inspector details { border-bottom: 1px solid var(--map-line); padding: 0 15px 12px; }
1048	.canvas-inspector summary { color: var(--map-text-soft); cursor: pointer; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; font-weight: 650; list-style: none; padding: 11px 0; }
1049	.canvas-inspector summary::after { color: var(--map-text-muted); content: "+"; float: right; }
1050	.canvas-inspector details[open] summary::after { content: "−"; }
1051	.canvas-inspector details > p { color: var(--map-text-muted); font-size: .8125rem; line-height: 1.55; }
1052	.inspector-facts { display: grid; margin: 0; }
1053	.inspector-endpoints { align-items: center; display: grid; gap: 6px; grid-template-columns: 1fr auto 1fr; }
1054	.inspector-endpoints button { background: rgba(255,255,255,.02); border: 1px solid var(--map-line); color: var(--map-text); display: grid; min-height: 48px; padding: 6px; text-align: left; }
1055	.inspector-endpoints small { color: var(--map-text-muted); font-size: .8125rem; text-transform: uppercase; }
1056	.inspector-endpoints strong { font-size: .8125rem; overflow-wrap: anywhere; }
1057	.inspector-endpoints > span { color: var(--map-focus); }
1058	.inspector-section-label { color: var(--map-text-muted); display: block; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; margin: 5px 0 3px; text-transform: uppercase; }
1059	.inspector-relation-list, .inspector-object-list, .inspector-flow-list { display: grid; }
1060	.inspector-relation-list button, .inspector-object-list button, .inspector-flow-list button { align-items: center; background: transparent; border: 0; border-top: 1px solid var(--map-line); color: var(--map-text-soft); display: grid; font-size: .8125rem; gap: 6px; min-height: 35px; padding: 5px 0; text-align: left; }
1061	.inspector-relation-list button { grid-template-columns: 13px minmax(0,1fr); }
1062	.inspector-relation-list small { color: var(--map-text-muted); grid-column: 2; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
1063	.inspector-object-list button { grid-template-columns: 18px 1fr; }
1064	.inspector-object-list b { color: var(--map-focus); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
1065	.inspector-flow-list button { grid-template-columns: 1fr auto; }
1066	.inspector-flow-list span { color: var(--map-text-muted); }
1067	.inspector-empty { color: var(--map-text-muted); font-size: .8125rem; padding: 4px 0; }
1068	.inspector-flow-steps { display: grid; gap: 7px; list-style: none; margin: 0; padding: 0; }
1069	.inspector-flow-steps li { align-items: flex-start; display: grid; gap: 7px; grid-template-columns: 20px 1fr; }
1070	.inspector-flow-steps li > b { align-items: center; border: 1px solid rgba(155,210,193,.35); color: var(--map-focus); display: flex; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; height: 20px; justify-content: center; }
1071	.inspector-flow-steps li > div { display: grid; }
1072	.inspector-flow-steps strong { color: var(--map-text-soft); font-size: .8125rem; }
1073	.inspector-flow-steps span { color: var(--map-text-muted); font-size: .8125rem; }
1074	.canvas-inspector pre { background: #0b1114; border: 1px solid var(--map-line); color: #8fa0a4; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; line-height: 1.55; max-height: 300px; overflow: auto; padding: 8px; white-space: pre-wrap; }
1075	
1076	.canvas-shell .canvas-statusbar { background: #0d1418; border-color: var(--map-line); color: var(--map-text-muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; min-height: 30px; padding: 4px 10px; }
1077	
1078	@media (max-width: 900px) {
1079	  .canvas-shell { grid-template-columns: 44px minmax(0,1fr); }
1080	  .canvas-nav-rail { padding-left: 3px; padding-right: 3px; }
1081	  .canvas-commandbar { gap: 5px; grid-template-columns: auto minmax(120px,1fr) auto; }
1082	  .canvas-command-actions button:nth-last-child(n+3) { display: none; }
1083	  .canvas-reading-key { display: none; }
1084	  .canvas-inspector { width: min(336px,88vw); }
1085	  .canvas-statusbar span:nth-child(2), .canvas-statusbar span:nth-child(3) { display: none; }
1086	}
