.architecture-topbar { align-items: center; background: var(--navy); color: #fff; display: flex; height: 76px; justify-content: space-between; padding: 0 28px; }
.architecture-topbar-left, .architecture-topbar-actions { align-items: center; display: flex; gap: 13px; }
.topbar-separator { background: rgba(255,255,255,.15); height: 34px; margin: 0 5px; width: 1px; }
.architecture-project-title { display: grid; }
.architecture-project-title small { color: #9cb4bb; font-size: .8125rem; line-height: 1.2; }
.architecture-project-title select { appearance: none; background: transparent; border: 0; color: #fff; font-size: .9375rem; font-weight: 800; min-height: 32px; outline: 0; padding: 0 30px 0 0; }
.architecture-project-title option { color: var(--ink-900); }
.architecture-topbar-actions .revision-chip { background: rgba(255,255,255,.07); border-color: rgba(255,255,255,.14); color: #b4c8cd; }
.architecture-topbar-actions .revision-chip b { color: #f2c47f; }
.change-live { align-items: center; color: #b9d8ce; display: inline-flex; font-size: .8125rem; gap: 7px; margin-right: 5px; }
.architecture-page-intro { align-items: center; display: flex; gap: 40px; justify-content: space-between; margin: 0 auto; max-width: 1680px; padding: 35px 30px 28px; }
.architecture-page-intro > div > span { color: var(--teal); }
.architecture-page-intro h1 { color: var(--ink-950); font-size: clamp(1.8rem,3vw,2.7rem); letter-spacing: -.04em; line-height: 1.15; margin-top: 4px; }
.architecture-page-intro > div > p { color: var(--ink-700); font-size: .9375rem; margin-top: 7px; max-width: 850px; }
.architecture-page-intro aside { background: var(--surface); border: 1px solid var(--line); border-radius: 13px; max-width: 390px; padding: 15px 18px; }
.architecture-page-intro aside strong { color: var(--teal); font-size: .8125rem; }
.architecture-page-intro aside p { color: var(--ink-600); font-size: .8125rem; line-height: 1.65; margin-top: 3px; }
.architecture-load-state, .architecture-empty-state { background: var(--surface); border: 1px solid var(--line); border-radius: 17px; box-shadow: var(--shadow-sm); margin: 0 auto; max-width: 1680px; min-height: 540px; padding: 100px 30px; text-align: center; }
.architecture-load-state strong, .architecture-empty-state h2 { color: var(--ink-950); display: block; font-size: 1.5rem; margin-top: 12px; }
.architecture-load-state p, .architecture-empty-state p { color: var(--ink-600); font-size: .9375rem; margin: 8px auto 0; max-width: 680px; }
.architecture-load-state.error { background: var(--red-soft); border-color: #f1cbc7; }
.architecture-load-state button, .architecture-empty-state button { background: var(--navy); border: 0; border-radius: 9px; color: #fff; font-size: .8125rem; font-weight: 800; margin-top: 20px; padding: 7px 16px; }
.loading-pulse { animation: loading-scale 1s ease-in-out infinite; background: var(--teal); border: 8px solid var(--teal-soft); border-radius: 50%; display: inline-block; height: 44px; width: 44px; }
@keyframes loading-scale { 50% { transform: scale(.82); } }
.architecture-empty-mark { display: flex; gap: 8px; height: 72px; justify-content: center; margin: 0 auto 20px; position: relative; width: 240px; }
.architecture-empty-mark i { background: var(--surface-soft); border: 2px solid var(--line-strong); border-radius: 10px; height: 56px; width: 66px; }
.architecture-empty-mark i:nth-child(2) { border-color: var(--teal); margin-top: 16px; }
.architecture-empty-state > small { color: var(--teal); font-size: .8125rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.architecture-empty-state a { color: var(--teal); display: block; font-size: .8125rem; font-weight: 800; margin-top: 14px; }
.architecture-workbench { background: var(--surface); border: 1px solid var(--line); border-radius: 17px; box-shadow: var(--shadow-sm); margin: 0 auto; max-width: 1680px; overflow: hidden; }
.architecture-workbench:fullscreen { background: var(--canvas); border: 0; border-radius: 0; height: 100vh; max-width: none; width: 100vw; }
.canvas-toolbar { align-items: center; background: var(--surface); border-bottom: 1px solid var(--line); display: flex; gap: 22px; justify-content: space-between; min-height: 66px; padding: 10px 14px 10px 20px; }
.canvas-breadcrumb, .canvas-breadcrumb span { align-items: center; display: flex; min-width: 0; }
.canvas-breadcrumb { overflow-x: auto; }
.canvas-breadcrumb button { background: transparent; border: 0; color: var(--ink-600); font-size: .8125rem; font-weight: 700; min-height: 38px; padding: 4px 7px; white-space: nowrap; }
.canvas-breadcrumb button.current { color: var(--ink-950); }
.canvas-breadcrumb i { color: var(--line-strong); font-style: normal; margin: 0 2px; }
.canvas-tools { align-items: center; display: flex; flex: 0 0 auto; gap: 6px; }
.canvas-tools > button { background: var(--surface-soft); border: 1px solid var(--line); border-radius: 8px; font-size: .8125rem; font-weight: 700; padding: 4px 10px; }
.canvas-tools > button:hover, .canvas-tools > button.active { background: var(--teal-soft); border-color: #b9dbd4; color: var(--teal); }
.canvas-tools > button b { background: var(--amber); border-radius: 99px; color: #fff; font-size: .8125rem; padding: 1px 5px; }
.canvas-search { position: relative; }
.canvas-search input { background: var(--surface-soft); border: 1px solid var(--line); border-radius: 8px; font-size: .8125rem; min-height: 40px; padding: 7px 11px; width: 190px; }
.canvas-search input:focus-visible, input:focus-visible { outline: 3px solid rgba(13,118,110,.25); outline-offset: 2px; }
.canvas-search-results { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; box-shadow: 0 14px 40px rgba(19,33,43,.16); display: grid; overflow: hidden; position: absolute; right: 0; top: 46px; width: 310px; z-index: 30; }
.canvas-search-results button { align-items: center; background: transparent; border: 0; border-bottom: 1px solid var(--line); display: grid; gap: 8px; grid-template-columns: 90px 1fr; padding: 9px 12px; text-align: left; }
.canvas-search-results button:last-child { border-bottom: 0; }
.canvas-search-results button:hover { background: var(--surface-soft); }
.canvas-search-results span { color: var(--teal); font-size: .8125rem; }
.canvas-search-results strong { font-size: .8125rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.revision-timeline { align-items: center; background: #f7faf9; border-bottom: 1px solid var(--line); display: grid; gap: 11px; grid-template-columns: auto auto minmax(180px,1fr) auto auto; min-height: 52px; padding: 7px 16px; }
.revision-timeline button { background: var(--navy); border: 0; border-radius: 8px; color: #fff; font-size: .8125rem; font-weight: 800; min-height: 34px; padding: 5px 12px; }
.revision-timeline button:disabled { opacity: .38; }
.revision-timeline small { color: var(--ink-600); font-size: .8125rem; font-weight: 800; white-space: nowrap; }
.revision-timeline input { accent-color: var(--teal); min-width: 0; width: 100%; }
.revision-timeline strong { color: var(--ink-950); font-size: .9375rem; }
.revision-timeline span { background: var(--teal-soft); border-radius: 99px; color: var(--teal); font-size: .8125rem; font-weight: 800; padding: 4px 9px; white-space: nowrap; }
.canvas-stage { display: flex; height: min(68vh,820px); min-height: 590px; position: relative; }
.architecture-workbench:fullscreen .canvas-stage { height: calc(100vh - 161px); }
.canvas-kernel-stage { flex: 1 1 auto; min-width: 0; position: relative; }
.canvas-stage .react-flow { background: #f8faf9; }
.architecture-node-card { background: var(--surface); border: 2px solid #b7d7d1; border-radius: 14px; box-shadow: 0 10px 26px rgba(19,33,43,.09); height: 168px; overflow: hidden; position: relative; width: 270px; }
.architecture-node-card.selected { border-color: var(--teal); box-shadow: 0 0 0 4px rgba(13,118,110,.13),0 14px 34px rgba(19,33,43,.12); }
.architecture-node-card.attention { border-color: #e2b56e; }
.architecture-node-card.flow-active { border-width: 2px; box-shadow: 0 12px 30px rgba(19,33,43,.13); }
.architecture-node-card > header { align-items: center; display: grid; gap: 10px; grid-template-columns: 38px minmax(0,1fr) auto; padding: 13px 14px 8px; }
.architecture-node-icon { align-items: center; background: var(--teal-soft); border-radius: 9px; color: var(--teal); display: flex; font-size: .8125rem; font-weight: 900; height: 38px; justify-content: center; width: 38px; }
.type-domain .architecture-node-icon { background: var(--blue-soft); color: var(--blue); }
.type-flow .architecture-node-icon { background: #f2edfb; color: #65469a; }
.type-interface .architecture-node-icon, .type-dataentity .architecture-node-icon { background: var(--amber-soft); color: var(--amber); }
.architecture-node-card header > div { display: grid; min-width: 0; }
.architecture-node-card header small { color: var(--ink-500); font-size: .8125rem; line-height: 1.2; }
.architecture-node-card header strong { color: var(--ink-950); font-size: .9375rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.knowledge-dot { background: var(--teal); border: 3px solid var(--teal-soft); border-radius: 50%; height: 12px; width: 12px; }
.knowledge-dot.state-inferred, .knowledge-dot.state-unknown, .knowledge-dot.state-stale { background: #d48a35; border-color: var(--amber-soft); }
.knowledge-dot.state-conflicted { background: var(--red); border-color: var(--red-soft); }
.architecture-node-card > p { color: var(--ink-600); display: -webkit-box; font-size: .8125rem; line-height: 1.5; margin: 0 14px; min-height: 38px; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.architecture-node-card > footer { align-items: center; border-top: 1px solid var(--line); bottom: 0; display: flex; justify-content: space-between; left: 0; min-height: 39px; padding: 5px 10px 5px 14px; position: absolute; right: 0; }
.architecture-node-card footer > span, .architecture-node-card footer em { color: var(--ink-500); font-size: .8125rem; font-style: normal; max-width: 110px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.architecture-node-card footer button { background: var(--teal-soft); border: 0; border-radius: 7px; color: var(--teal); font-size: .8125rem; font-weight: 800; min-height: 29px; padding: 2px 8px; }
.architecture-node-card footer button b { font-size: .9375rem; margin-left: 3px; }
.timeline-node-state { background: var(--amber-soft); border-radius: 0 0 0 8px; color: #9a5b14; font-size: .8125rem; font-weight: 900; padding: 3px 7px; position: absolute; right: 0; top: 0; }
.timeline-node-state.added { background: var(--teal-soft); color: var(--teal); }
.flow-step-strip { display: flex; gap: 5px; margin: 6px 12px 0; overflow: hidden; }
.flow-step-strip span { align-items: center; background: #f7faf9; border: 1px solid var(--line); border-left-width: 3px; border-radius: 6px; color: var(--ink-700); display: flex; flex: 0 1 auto; font-size: .8125rem; gap: 4px; max-width: 112px; min-width: 0; overflow: hidden; padding: 3px 5px 3px 3px; text-overflow: ellipsis; white-space: nowrap; }
.flow-step-strip span b { align-items: center; border-radius: 4px; color: #fff; display: inline-flex; flex: 0 0 auto; font-size: .8125rem; height: 20px; justify-content: center; width: 20px; }
.flow-step-strip > em { color: var(--ink-500); font-size: .8125rem; font-style: normal; padding-top: 4px; }
.architecture-handle { background: var(--teal) !important; border: 3px solid var(--surface) !important; height: 10px !important; width: 10px !important; }
.architecture-node-dimmed { opacity: .18; }
.architecture-edge path { stroke: #6d898e; }
.architecture-edge.state-inferred path, .architecture-edge.state-unknown path, .architecture-edge.state-stale path { stroke: #c58742; stroke-dasharray: 7 5; }
.architecture-edge.state-conflicted path { stroke: var(--red); stroke-dasharray: 5 4; }
.react-flow__edge-text { fill: var(--ink-600); font-size: .8125rem; font-weight: 700; }
.react-flow__edge-textbg { fill: #f8faf9; fill-opacity: .9; }
.architecture-controls { border: 1px solid var(--line) !important; border-radius: 10px !important; box-shadow: var(--shadow-sm) !important; overflow: hidden; }
.architecture-controls button { background: var(--surface) !important; border-bottom-color: var(--line) !important; }
.architecture-minimap { background: rgba(255,255,255,.94) !important; border: 1px solid var(--line); border-radius: 10px; box-shadow: var(--shadow-sm); }
.canvas-legend { align-items: center; background: rgba(255,255,255,.94); border: 1px solid var(--line); border-radius: 10px; bottom: 18px; display: flex; gap: 13px; left: 62px; padding: 8px 11px; position: absolute; z-index: 6; }
.canvas-legend span { align-items: center; color: var(--ink-600); display: flex; font-size: .8125rem; gap: 6px; }
.canvas-legend span i { background: var(--teal); border-radius: 50%; height: 8px; width: 8px; }
.canvas-legend span i.inferred { background: #c58742; }
.canvas-legend span i.attention { background: var(--red); }
.canvas-legend span i.flowing { animation: flow-legend-pulse 1.3s ease-in-out infinite; background: var(--teal); box-shadow: 0 0 0 4px rgba(13,118,110,.13); }
.canvas-legend span i.timeline-change { background: var(--amber); border-radius: 2px; }
.canvas-legend em { border-left: 1px solid var(--line); color: var(--ink-500); font-size: .8125rem; font-style: normal; padding-left: 13px; }
@keyframes flow-legend-pulse { 50% { opacity: .35; transform: scale(.7); } }
.flow-library { background: #f4f8f7; border-right: 1px solid var(--line); box-shadow: 10px 0 26px rgba(19,33,43,.035); flex: 0 0 330px; overflow-y: auto; padding: 18px 14px; position: relative; z-index: 7; }
.flow-library > header { align-items: flex-start; display: flex; justify-content: space-between; }
.flow-library > header > div { display: grid; }
.flow-library > header small { color: var(--teal); font-size: .8125rem; font-weight: 900; letter-spacing: .06em; }
.flow-library > header strong { color: var(--ink-950); font-size: 1.15rem; margin-top: 2px; }
.flow-library > header button, .flow-solo { background: transparent; border: 1px solid var(--line); border-radius: 7px; color: var(--ink-600); font-size: .8125rem; font-weight: 800; min-height: 30px; padding: 4px 8px; }
.flow-library > p { color: var(--ink-600); font-size: .8125rem; line-height: 1.6; margin: 9px 0 14px; }
.flow-budget-warning { background: var(--amber-soft); border: 1px solid #edcca2; border-radius: 8px; color: #8a571b; font-size: .8125rem; line-height: 1.5; margin-bottom: 10px; padding: 8px 9px; }
.flow-list { display: grid; gap: 9px; }
.flow-list article { background: var(--surface); border: 1px solid var(--line); border-radius: 11px; padding: 11px; transition: border-color 150ms ease,box-shadow 150ms ease; }
.flow-list article.active { border-color: var(--flow-color); box-shadow: inset 3px 0 0 var(--flow-color),0 7px 18px rgba(19,33,43,.06); }
.flow-toggle { align-items: center; background: transparent; border: 0; display: grid; gap: 9px; grid-template-columns: 11px 1fr; padding: 0; text-align: left; width: 100%; }
.flow-toggle > i { border: 2px solid var(--flow-color); border-radius: 50%; height: 11px; width: 11px; }
.flow-list article.active .flow-toggle > i { background: var(--flow-color); box-shadow: 0 0 0 3px color-mix(in srgb,var(--flow-color) 17%,transparent); }
.flow-toggle span { display: grid; min-width: 0; }
.flow-toggle strong { color: var(--ink-950); font-size: .8125rem; line-height: 1.35; }
.flow-toggle small { color: var(--ink-500); font-size: .8125rem; margin-top: 2px; }
.flow-list article > p { color: var(--ink-600); display: -webkit-box; font-size: .8125rem; line-height: 1.5; margin: 8px 0; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.flow-list article > dl { display: grid; gap: 4px; margin: 0 0 8px; }
.flow-list article > dl div { display: grid; gap: 5px; grid-template-columns: 31px 1fr; }
.flow-list article dt { color: var(--ink-500); font-size: .8125rem; }
.flow-list article dd { color: var(--ink-800); font-size: .8125rem; margin: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.flow-solo { min-height: 27px; width: 100%; }
.flow-solo:hover { border-color: var(--flow-color); color: var(--flow-color); }
.flow-empty { border: 1px dashed var(--line-strong); border-radius: 10px; color: var(--ink-500); font-size: .8125rem; line-height: 1.6; padding: 14px; }
.architecture-flow-edge path { filter: drop-shadow(0 1px 1px rgba(255,255,255,.95)); }
.flow-packet { filter: drop-shadow(0 0 3px rgba(255,255,255,.9)); pointer-events: none; }
.flow-edge-label { align-items: center; background: rgba(255,255,255,.96); border: 1px solid; border-radius: 7px; box-shadow: 0 3px 10px rgba(19,33,43,.08); color: var(--ink-800); display: flex; font-size: .8125rem; gap: 5px; max-width: 170px; padding: 3px 7px 3px 3px; pointer-events: all; position: absolute; }
.flow-edge-label b { align-items: center; border-radius: 4px; color: #fff; display: inline-flex; flex: 0 0 auto; height: 18px; justify-content: center; width: 18px; }
.flow-edge-label span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.canvas-layouting { align-items: center; background: rgba(248,250,249,.9); bottom: 0; color: var(--teal); display: flex; font-size: .875rem; font-weight: 800; justify-content: center; left: 0; position: absolute; right: 0; top: 0; z-index: 10; }
.canvas-leaf-state { background: rgba(255,255,255,.95); border: 1px solid var(--line); border-radius: 13px; left: 50%; padding: 24px 30px; position: absolute; text-align: center; top: 50%; transform: translate(-50%,-50%); }
.canvas-leaf-state p { color: var(--ink-600); font-size: .8125rem; margin-top: 4px; }
.node-inspector { background: rgba(255,255,255,.98); border-left: 1px solid var(--line); bottom: 0; box-shadow: -16px 0 36px rgba(19,33,43,.08); overflow-y: auto; padding: 22px; position: absolute; right: 0; top: 0; transform: translateX(104%); transition: transform 220ms ease; width: 350px; z-index: 8; }
.node-inspector.open { transform: translateX(0); }
.node-inspector > header { align-items: center; display: flex; justify-content: space-between; }
.node-inspector > header span { color: var(--teal); font-size: .8125rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.node-inspector > header button { background: var(--surface-soft); border: 1px solid var(--line); border-radius: 8px; font-size: 1.25rem; min-height: 34px; width: 34px; }
.node-inspector > h2 { color: var(--ink-950); font-size: 1.55rem; letter-spacing: -.03em; line-height: 1.2; margin-top: 18px; }
.node-inspector > p { color: var(--ink-700); font-size: .875rem; line-height: 1.7; margin-top: 10px; }
.inspector-state { align-items: center; background: var(--surface-soft); border-radius: 9px; display: flex; gap: 7px; margin-top: 18px; padding: 9px 11px; }
.inspector-state i { background: var(--teal); border-radius: 50%; height: 9px; width: 9px; }
.inspector-state i.state-inferred, .inspector-state i.state-unknown, .inspector-state i.state-stale { background: #c58742; }
.inspector-state i.state-conflicted { background: var(--red); }
.inspector-state span { color: var(--ink-700); font-size: .8125rem; }
.inspector-state b { color: var(--ink-500); font-size: .8125rem; margin-left: auto; }
.node-inspector dl { display: grid; margin: 20px 0 0; }
.node-inspector dl div { border-bottom: 1px solid var(--line); padding: 10px 0; }
.node-inspector dt { color: var(--ink-500); font-size: .8125rem; }
.node-inspector dd { color: var(--ink-900); font-size: .8125rem; margin: 2px 0 0; overflow-wrap: anywhere; }
.node-inspector > section { margin-top: 22px; }
.node-inspector > section > small { color: var(--ink-500); font-size: .8125rem; font-weight: 800; }
.node-inspector > section article { align-items: center; border-bottom: 1px solid var(--line); display: grid; gap: 7px; grid-template-columns: 92px 18px 1fr; padding: 9px 0; }
.node-inspector > section article b { color: var(--teal); font-size: .8125rem; }
.node-inspector > section article span { color: var(--ink-500); font-size: .8125rem; }
.node-inspector > section article strong { font-size: .8125rem; overflow-wrap: anywhere; }
.node-inspector > section.flow-step-inspector article { align-items: stretch; background: #f7faf9; border: 1px solid var(--line); border-radius: 10px; display: block; margin-top: 9px; padding: 10px; }
.flow-step-inspector article > header { align-items: center; display: grid; gap: 7px; grid-template-columns: 22px 1fr auto; }
.flow-step-inspector article > header b { align-items: center; background: var(--teal); border-radius: 5px; color: #fff; display: flex; font-size: .8125rem; height: 22px; justify-content: center; }
.flow-step-inspector article > header strong { color: var(--ink-950); font-size: .8125rem; }
.flow-step-inspector article > header span { background: var(--teal-soft); border-radius: 99px; color: var(--teal); font-size: .8125rem; font-weight: 800; padding: 3px 6px; }
.flow-step-inspector article > small { color: var(--ink-500); display: block; font-size: .8125rem; margin: 6px 0 0 29px; }
.node-inspector .flow-step-inspector article dl { margin-top: 8px; }
.node-inspector .flow-step-inspector article dl div { border-bottom: 1px dashed var(--line); display: grid; gap: 7px; grid-template-columns: 70px 1fr; padding: 6px 0; }
.node-inspector .flow-step-inspector article dl div:last-child { border-bottom: 0; }
.node-inspector .flow-step-inspector article dd { margin: 0; }
.inspector-drill { background: var(--navy); border: 0; border-radius: 9px; color: #fff; font-size: .8125rem; font-weight: 800; margin-top: 22px; padding: 8px 14px; width: 100%; }
.canvas-statusbar { align-items: center; background: var(--surface); border-top: 1px solid var(--line); color: var(--ink-500); display: flex; font-size: .8125rem; justify-content: space-between; min-height: 43px; padding: 6px 16px; }

@media (max-width: 1500px) {
  .portal-stats, .project-collection, .portal-footer { margin-left: 28px; margin-right: 28px; }
  .architecture-workbench, .architecture-load-state, .architecture-empty-state { margin-left: 28px; margin-right: 28px; }
}
@media (max-width: 1100px) {
  .portal-hero { gap: 40px; grid-template-columns: 1fr 340px; }
  .portal-stats { grid-template-columns: repeat(3,1fr); }
  .portal-stats article { border-bottom: 1px solid var(--line); }
  .project-card-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .canvas-toolbar { align-items: flex-start; flex-direction: column; }
