import assert from "node:assert/strict";
import { register } from "node:module";
import test from "node:test";

register("./cloudflare-loader.mjs", import.meta.url);

const developmentPreviewMeta =
  /<meta(?=[^>]*\bname=["']codex-preview["'])(?=[^>]*\bcontent=["']development["'])[^>]*>/i;

test("renders development preview metadata", async () => {
  const workerUrl = new URL("../dist/server/index.js", import.meta.url);
  workerUrl.searchParams.set("test", `${process.pid}-${Date.now()}`);
  const { default: worker } = await import(workerUrl.href);

  const response = await worker.fetch(
    new Request("http://localhost/", {
      headers: { accept: "text/html" },
    }),
    {
      ASSETS: {
        fetch: async () => new Response("Not found", { status: 404 }),
      },
    },
    {
      waitUntil() {},
      passThroughOnException() {},
    },
  );

  assert.equal(response.status, 200);
  assert.match(
    response.headers.get("content-type") ?? "",
    /^text\/html\b/i,
  );
  assert.match(await response.text(), developmentPreviewMeta);
});
import assert from "node:assert/strict";
import test from "node:test";

import {
  AGENT_PROTOCOL_VERSION,
  ARCHITECTURE_FLOW_ROLES,
  canTransitionChange,
  canTransitionKnowledge,
  CHANGE_STATES,
  ENGINEERING_EVENT_TYPES,
  KNOWLEDGE_STATES,
  ONTOLOGY_ENTITY_TYPES,
  ONTOLOGY_RELATION_TYPES,
} from "../app/domain/foundation.ts";

test("publishes the bounded Foundation vocabulary", () => {
  assert.equal(AGENT_PROTOCOL_VERSION, "v0.3");
  assert.equal(ONTOLOGY_ENTITY_TYPES.length, 14);
  assert.equal(ONTOLOGY_RELATION_TYPES.length, 14);
  assert.deepEqual(ARCHITECTURE_FLOW_ROLES, ["entry", "producer", "transformer", "router", "guard", "consumer", "side_effect", "exit"]);
  assert.equal(KNOWLEDGE_STATES.length, 6);
  assert.equal(CHANGE_STATES.length, 8);
  assert.equal(ENGINEERING_EVENT_TYPES.length, 21);
});

test("rejects lifecycle shortcuts and permits evidence-backed transitions", () => {
  assert.equal(canTransitionChange("SCOPING", "PLANNED"), true);
  assert.equal(canTransitionChange("SCOPING", "COMPLETED"), false);
  assert.equal(canTransitionChange("VERIFYING", "EXECUTING"), true);
  assert.equal(canTransitionKnowledge("UNKNOWN", "CONFIRMED"), true);
  assert.equal(canTransitionKnowledge("INFERRED", "AUTHORITATIVE"), false);
  assert.equal(canTransitionKnowledge("CONFIRMED", "STALE"), true);
});
