import { mkdir, writeFile } from "node:fs/promises";
import { register } from "node:module";
import path from "node:path";

register("../tests/cloudflare-loader.mjs", import.meta.url);

const { COMPLEX_CANVAS_FIXTURE, SMALL_CANVAS_FIXTURE } = await import("../app/architecture/fixtures.ts");
const { deriveCanvasView, visibleObjectIds } = await import("../app/architecture/interaction.ts");
const { layoutSemanticGraph } = await import("../app/architecture/layout.ts");

const escape = (value) => String(value)
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;");

function routePath(points) {
  return points.length < 2 ? "" : `M ${points.map((point) => `${point.x} ${point.y}`).join(" L ")}`;
}

function render(graph, layout, view, title, note) {
  const margin = 54;
  const footer = 94;
  const width = Math.max(1200, layout.width + margin * 2);
  const height = Math.max(760, layout.height + margin * 2 + footer);
  const activeFlow = view.activeFlowId ? graph.flows.find((flow) => flow.id === view.activeFlowId) : null;
  const visibleIds = visibleObjectIds(graph, view);
  const regions = [...graph.regions].sort((left, right) => (layout.regionRects[left.id]?.depth ?? 0) - (layout.regionRects[right.id]?.depth ?? 0));
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="1050" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(title)}">
  <defs>
    <pattern id="grid" width="28" height="28" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#81949a" opacity=".13"/></pattern>
    <marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#84969b"/></marker>
    <marker id="arrow-active" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#d8f2e8"/></marker>
    <style>
      .ui{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
      .region{fill:#53676d;fill-opacity:.025;stroke:#9fb3b8;stroke-opacity:.17;stroke-width:1}.region.nested{stroke-dasharray:7 6;stroke-opacity:.12}
      .edge{fill:none;stroke:#73868b;stroke-width:1.3;marker-end:url(#arrow)}.edge.muted{stroke-opacity:.09}.edge.related{stroke:#7fa9a0;stroke-width:1.7}.edge.active{stroke:#d8f2e8;stroke-width:3;marker-end:url(#arrow-active)}
      .node{fill:#131c21;stroke:#b9cdd1;stroke-opacity:.38;stroke-width:1}.node.primary{fill:#17262b;stroke:#d8f2e8;stroke-opacity:.9;stroke-width:2}.node.context{fill:#10181c;stroke-opacity:.2}.node.muted{fill:#0f1518;stroke-opacity:.1}
      .type{fill:#819398;font-size:13px;letter-spacing:1.1px}.name{fill:#edf2f1;font-size:17px;font-weight:650}.name.muted{fill:#94a2a5}.region-name{fill:#9eafb2;font-size:15px;font-weight:620}.region-type{fill:#708186;font-size:13px;letter-spacing:1px}.status{fill:#7f9196;font-size:13px}.title{fill:#edf2f1;font-size:21px;font-weight:680}.subtitle{fill:#91a3a7;font-size:13px}
    </style>
  </defs>
  <rect width="100%" height="100%" fill="#0b1013"/><rect width="100%" height="${height - footer}" fill="url(#grid)"/>
  <g transform="translate(${margin} ${margin})">
    ${regions.map((region) => {
      const rect = layout.regionRects[region.id];
      return rect ? `<g><rect class="region ${rect.depth > 0 ? "nested" : ""}" x="${rect.x}" y="${rect.y}" width="${rect.width}" height="${rect.height}"/><text class="ui region-type" x="${rect.x + 16}" y="${rect.y + 24}">REGION</text><text class="ui region-name" x="${rect.x + 84}" y="${rect.y + 24}">${escape(region.name)}</text></g>` : "";
    }).join("")}
    ${graph.relationships.filter((relationship) => visibleIds.has(relationship.sourceObjectId) && visibleIds.has(relationship.targetObjectId)).map((relationship) => {
      const route = layout.relationshipRoutes[relationship.id];
      if (!route) return "";
      const emphasis = view.relationshipEmphasis.get(relationship.id) ?? "normal";
      return `<path class="edge ${emphasis}" d="${routePath(route.points)}"/>`;
    }).join("")}
    ${graph.objects.filter((object) => visibleIds.has(object.id)).map((object) => {
      const rect = layout.objectRects[object.id];
      if (!rect) return "";
      const emphasis = view.objectEmphasis.get(object.id) ?? "normal";
      const truncated = object.name.length > 38 ? `${object.name.slice(0, 36)}…` : object.name;
      return `<g><rect class="node ${emphasis}" x="${rect.x}" y="${rect.y}" width="${rect.width}" height="${rect.height}"/><rect x="${rect.x}" y="${rect.y}" width="3" height="${rect.height}" fill="${emphasis === "primary" ? "#d8f2e8" : "#799793"}" opacity="${emphasis === "muted" ? ".25" : ".9"}"/><text class="mono type" x="${rect.x + 15}" y="${rect.y + 26}">${escape(object.objectType.toUpperCase())} · ${escape(object.state.label.toUpperCase())}</text><text class="ui name ${emphasis === "muted" ? "muted" : ""}" x="${rect.x + 15}" y="${rect.y + 58}">${escape(truncated)}</text></g>`;
    }).join("")}
===
