33	const KNOWLEDGE_COPY: Record<string, string> = {
34	  AUTHORITATIVE: "规则",
35	  CONFIRMED: "已验证",
36	  INFERRED: "推断",
37	  UNKNOWN: "未知",
38	  STALE: "可能过期",
39	  CONFLICTED: "存在冲突",
40	};
