83	  if (normalized === "CONFLICTED") return { value: "conflicted", label: KNOWLEDGE_COPY[normalized], severity: "critical", source: "knowledge" };
84	  if (["INFERRED", "UNKNOWN", "STALE"].includes(normalized)) return { value: normalized.toLowerCase(), label: KNOWLEDGE_COPY[normalized], severity: "attention", source: "knowledge" };
85	  return { value: normalized.toLowerCase(), label: KNOWLEDGE_COPY[normalized] ?? normalized, severity: "positive", source: "knowledge" };
