114	function regionOrder(entity: ArchitectureEntity, index: number) {
115	  const explicit = Number((entity as ArchitectureEntity & { order?: unknown }).order);
116	  return Number.isFinite(explicit) ? explicit : index;
117	}
118	
119	function semanticFlowStep(step: ArchitectureFlowStep): SemanticFlowStep {
120	  return {
121	    id: step.stepKey,
122	    objectId: step.entityKey,
123	    sequence: step.sequence,
124	    role: step.role,
125	    title: step.title,
126	    inputs: parseStringArray(step.inputsJson),
127	    action: step.action,
128	    outputs: parseStringArray(step.outputsJson),
129	    stateReads: parseStringArray(step.stateReadsJson),
130	    stateWrites: parseStringArray(step.stateWritesJson),
131	    failureModes: parseStringArray(step.failureModesJson),
