141	export function adaptArchitectureToSemanticGraph(input: ArchitectureSemanticInput): SemanticGraph {
142	  const entities = [...input.entities].sort((left, right) => left.entityKey.localeCompare(right.entityKey));
143	  const entityByKey = new Map(entities.map((entity) => [entity.entityKey, entity]));
144	  const regionEntities = entities.filter((entity) => entity.entityType === "Domain" || entity.entityType === "Project");
145	  const regionEntityKeys = new Set(regionEntities.map((entity) => entity.entityKey));
146	  const syntheticRegionId = `${input.projectId}:region:unscoped`;
147	
148	  function nearestRegionId(entity: ArchitectureEntity) {
149	    let cursor = entity.parentEntityKey ? entityByKey.get(entity.parentEntityKey) : undefined;
150	    const seen = new Set<string>();
151	    while (cursor && !seen.has(cursor.entityKey)) {
152	      if (regionEntityKeys.has(cursor.entityKey)) return cursor.entityKey;
153	      seen.add(cursor.entityKey);
154	      cursor = cursor.parentEntityKey ? entityByKey.get(cursor.parentEntityKey) : undefined;
155	    }
156	    return syntheticRegionId;
157	  }
158	
159	  const regions: SemanticRegion[] = regionEntities.map((entity, index) => ({
160	    id: entity.entityKey,
161	    name: entity.name,
162	    summary: entity.summary,
163	    parentRegionId: entity.parentEntityKey && regionEntityKeys.has(entity.parentEntityKey) ? entity.parentEntityKey : undefined,
164	    order: regionOrder(entity, index),
165	    importance: importance(entity.parentEntityKey ? 66 : 88),
166	    metadata: {
167	      canonicalEntityType: entity.entityType,
168	      canonicalEntityKey: entity.entityKey,
169	      knowledgeState: entity.knowledgeState,
170	      lifecycleStatus: entity.lifecycleStatus,
171	      sourceObservationId: entity.sourceObservationId,
172	      validFromRevision: entity.validFromRevision,
173	      validToRevision: entity.validToRevision,
174	    },
175	  }));
176	
177	  const objectEntities = entities.filter((entity) => !regionEntityKeys.has(entity.entityKey));
178	  if (objectEntities.some((entity) => nearestRegionId(entity) === syntheticRegionId) || regions.length === 0) {
179	    regions.push({
180	      id: syntheticRegionId,
181	      name: regions.length === 0 ? input.projectName : "Project Services",
182	      summary: regions.length === 0 ? "Project scope" : "Objects without an explicit Domain boundary.",
183	      order: Number.MAX_SAFE_INTEGER,
184	      importance: importance(regions.length === 0 ? 88 : 40),
185	      metadata: { synthetic: true },
186	    });
187	  }
188	
189	  const degree = new Map<string, number>();
190	  for (const relation of input.relations) {
191	    degree.set(relation.sourceEntityKey, (degree.get(relation.sourceEntityKey) ?? 0) + 1);
192	    degree.set(relation.targetEntityKey, (degree.get(relation.targetEntityKey) ?? 0) + 1);
193	  }
194	
195	  const objects: SemanticObject[] = objectEntities.map((entity, index) => {
196	    const entityDegree = degree.get(entity.entityKey) ?? 0;
197	    const score = Math.min(98, 42 + entityDegree * 7 + (entity.entityType === "DataEntity" ? 9 : 0));
198	    return {
199	      id: entity.entityKey,
200	      name: entity.name,
201	      summary: entity.summary,
202	      objectType: objectType(entity),
203	      regionId: nearestRegionId(entity),
204	      state: stateFromKnowledge(entity.knowledgeState, input.timelineStates?.get(entity.entityKey)),
205	      importance: importance(score),
206	      metadata: {
207	        canonicalEntityType: entity.entityType,
208	        canonicalEntityKey: entity.entityKey,
209	        technology: entity.technology,
210	        repositoryRefs: parseStringArray(entity.repositoryRefsJson),
211	        knowledgeState: entity.knowledgeState,
212	        lifecycleStatus: entity.lifecycleStatus,
213	        sourceObservationId: entity.sourceObservationId,
214	        validFromRevision: entity.validFromRevision,
215	        validToRevision: entity.validToRevision,
216	        degree: entityDegree,
217	        parentEntityKey: entity.parentEntityKey,
218	      },
219	      layoutHints: { order: index },
220	    };
221	  });
222	
223	  const objectIds = new Set(objects.map((object) => object.id));
224	  const relationships: SemanticRelationship[] = input.relations
225	    .filter((relation) => objectIds.has(relation.sourceEntityKey) && objectIds.has(relation.targetEntityKey))
226	    .map((relation, index) => {
227	      const type = relationshipType(relation.relationType);
228	      return {
229	        id: relation.relationKey,
230	        sourceObjectId: relation.sourceEntityKey,
231	        targetObjectId: relation.targetEntityKey,
232	        relationshipType: type,
233	        direction: "directed",
234	        label: relation.label || relation.relationType.replaceAll("_", " "),
235	        summary: relation.summary,
236	        state: stateFromKnowledge(relation.knowledgeState),
237	        importance: importance(type === "control" || type === "event" ? 62 : 54),
238	        metadata: {
239	          canonicalRelationType: relation.relationType,
240	          knowledgeState: relation.knowledgeState,
241	          evidenceRefs: parseStringArray(relation.evidenceRefsJson),
242	          lifecycleStatus: relation.lifecycleStatus,
243	          sourceObservationId: relation.sourceObservationId,
244	          validFromRevision: relation.validFromRevision,
245	          validToRevision: relation.validToRevision,
246	          flowIds: [] as string[],
247	        },
248	        layoutHints: { ...relationshipPortHints(type), order: index },
249	      } satisfies SemanticRelationship;
250	    });
251	
252	  const relationshipByEndpoints = new Map<string, SemanticRelationship[]>();
253	  for (const relationship of relationships) {
254	    const key = `${relationship.sourceObjectId}\u0000${relationship.targetObjectId}`;
255	    relationshipByEndpoints.set(key, [...(relationshipByEndpoints.get(key) ?? []), relationship]);
256	  }
257	
258	  const flowStepsByFlow = new Map<string, ArchitectureFlowStep[]>();
259	  for (const step of input.flowSteps) {
260	    const values = flowStepsByFlow.get(step.flowKey) ?? [];
261	    values.push(step);
262	    flowStepsByFlow.set(step.flowKey, values);
263	  }
264	
265	  const flows: SemanticFlow[] = input.flows.map((flow) => {
266	    const steps = (flowStepsByFlow.get(flow.flowKey) ?? [])
267	      .filter((step) => objectIds.has(step.entityKey))
268	      .sort((left, right) => left.sequence - right.sequence || left.stepKey.localeCompare(right.stepKey));
269	    const semanticSteps = steps.map(semanticFlowStep);
270	    const stepById = new Map(steps.map((step) => [step.stepKey, step]));
271	    const relationshipIds = new Set<string>();
272	
273	    for (const step of steps) {
274	      for (const nextStepKey of parseStringArray(step.nextStepKeysJson)) {
275	        const next = stepById.get(nextStepKey);
276	        if (!next || next.entityKey === step.entityKey) continue;
277	        const candidates = relationshipByEndpoints.get(`${step.entityKey}\u0000${next.entityKey}`) ?? [];
278	        const existing = candidates.find((candidate) => candidate.relationshipType === "data") ?? candidates[0];
279	        if (existing) {
280	          relationshipIds.add(existing.id);
281	          const flowIds = existing.metadata.flowIds as string[];
282	          if (!flowIds.includes(flow.flowKey)) flowIds.push(flow.flowKey);
283	          continue;
284	        }
285	        const outputs = parseStringArray(step.outputsJson);
286	        const inputs = parseStringArray(next.inputsJson);
287	        const payload = outputs.length > 0 ? outputs.join(" + ") : inputs.join(" + ");
288	        const relationship: SemanticRelationship = {
289	          id: `${flow.flowKey}:relationship:${step.stepKey}:${next.stepKey}`,
290	          sourceObjectId: step.entityKey,
291	          targetObjectId: next.entityKey,
292	          relationshipType: "data",
293	          direction: "directed",
294	          label: payload || `${step.title} → ${next.title}`,
295	          summary: `${step.title} → ${next.title}`,
296	          state: stateFromKnowledge(flow.knowledgeState),
297	          importance: importance(72),
298	          metadata: {
299	            synthetic: true,
300	            flowIds: [flow.flowKey],
301	            fromStepId: step.stepKey,
302	            toStepId: next.stepKey,
303	          },
304	          layoutHints: relationshipPortHints("data"),
305	        };
306	        relationships.push(relationship);
307	        relationshipIds.add(relationship.id);
308	        relationshipByEndpoints.set(`${step.entityKey}\u0000${next.entityKey}`, [relationship]);
309	      }
310	    }
311	
312	    return {
313	      id: flow.flowKey,
314	      name: flow.name,
315	      description: flow.summary,
316	      objectIds: [...new Set(steps.map((step) => step.entityKey))],
317	      relationshipIds: [...relationshipIds],
318	      steps: semanticSteps,
319	      state: stateFromKnowledge(flow.knowledgeState),
320	      importance: importance(78),
321	      metadata: {
322	        trigger: flow.trigger,
323	        outcome: flow.outcome,
324	        knowledgeState: flow.knowledgeState,
325	        lifecycleStatus: flow.lifecycleStatus,
326	        sourceObservationId: flow.sourceObservationId,
327	        validFromRevision: flow.validFromRevision,
328	        validToRevision: flow.validToRevision,
329	      },
330	    };
331	  });
332	
333	  return {
334	    id: `${input.projectId}:r${input.revision}`,
335	    version: SEMANTIC_GRAPH_VERSION,
336	    name: input.projectName,
337	    regions,
338	    objects,
339	    relationships,
340	    flows,
341	    scope: {
342	      projectId: input.projectId,
343	      revision: input.revision,
344	      kind: "project",
345	      source: input.source ?? "registry",
346	    },
347	    metadata: {
348	      canonicalEntityCount: input.entities.length,
349	      canonicalRelationCount: input.relations.length,
350	      generatedAtRevision: input.revision,
351	    },
352	  };
353	}
