export type TraceCorridorStep = {
  step: SemanticFlowStep;
  object?: SemanticObject;
  isEntry: boolean;
  isExit: boolean;
};

export type TraceCorridorTransition = {
  fromStepId: string;
  toStepId: string;
  fromSequence: number;
  toSequence: number;
  relationshipId?: string;
  payload: string;
};

export type TraceCorridor = {
  flow: SemanticFlow;
  steps: TraceCorridorStep[];
  transitions: TraceCorridorTransition[];
};

// Trace is a lens over the stable map: the ordered main path from the entry
// step to the outcome, with the payload each hand-off carries.
export function deriveTraceCorridor(graph: SemanticGraph, flowId: string | null): TraceCorridor | null {
  if (!flowId) return null;
  const index = indexSemanticGraph(graph);
  const flow = index.flowById.get(flowId);
  if (!flow) return null;

  const stepById = new Map(flow.steps.map((step) => [step.id, step]));
  const reachedIds = new Set<string>();
  for (const step of flow.steps) for (const nextStepId of step.nextStepIds) reachedIds.add(nextStepId);

  const steps: TraceCorridorStep[] = [...flow.steps]
    .sort((left, right) => left.sequence - right.sequence || left.id.localeCompare(right.id))
    .map((step) => ({
      step,
      object: index.objectById.get(step.objectId),
      isEntry: step.role === "entry" || !reachedIds.has(step.id),
      isExit: step.role === "exit" || step.nextStepIds.length === 0,
    }));

  const transitions: TraceCorridorTransition[] = [];
  for (const step of flow.steps) {
    for (const nextStepId of step.nextStepIds) {
      const next = stepById.get(nextStepId);
      if (!next) continue;
      const payload = step.outputs.length > 0 ? step.outputs.join(" + ") : next.inputs.join(" + ");
      const relationship = graph.relationships.find((candidate) =>
        candidate.metadata.fromStepId === step.id && candidate.metadata.toStepId === nextStepId)
        ?? graph.relationships.find((candidate) =>
          Array.isArray(candidate.metadata.flowIds)
          && (candidate.metadata.flowIds as string[]).includes(flow.id)
          && candidate.sourceObjectId === step.objectId
          && candidate.targetObjectId === next.objectId);
      transitions.push({
        fromStepId: step.id,
        toStepId: nextStepId,
        fromSequence: step.sequence,
        toSequence: next.sequence,
        relationshipId: relationship?.id,
        payload: payload || `${step.title} → ${next.title}`,
      });
    }
  }
  transitions.sort((left, right) => left.fromSequence - right.fromSequence || left.toSequence - right.toSequence);

  return { flow, steps, transitions };
}

