import { MarkerType, type Edge, type Node } from "@xyflow/react";
import { visibleObjectIds, type CanvasViewModel } from "./interaction";
import type { CanvasLayout } from "./layout";
import { indexSemanticGraph, type SemanticFlowStep, type SemanticGraph } from "./semantic-graph";
import type { ObjectNodeData, RegionNodeData, RelationshipEdgeData, RegionSummary } from "./types";

export type CanvasObjectNode = Node<ObjectNodeData, "object">;
export type CanvasRegionNode = Node<RegionNodeData, "region">;
export type CanvasNode = CanvasObjectNode | CanvasRegionNode;
export type CanvasRelationshipEdge = Edge<RelationshipEdgeData, "relationship">;

// A Region border must pay for its space with a readable summary of what it
// contains — especially at Landscape, where low-importance objects are hidden.
export function summarizeRegions(graph: SemanticGraph): Map<string, RegionSummary> {
  const index = indexSemanticGraph(graph);
  const memberIds = new Map<string, Set<string>>();
  const collect = (regionId: string, seen = new Set<string>()): Set<string> => {
    const cached = memberIds.get(regionId);
    if (cached) return cached;
    if (seen.has(regionId)) return new Set();
    seen.add(regionId);
    const members = new Set<string>();
    for (const object of index.objectsByRegionId.get(regionId) ?? []) members.add(object.id);
    for (const child of index.childRegionsByRegionId.get(regionId) ?? []) for (const id of collect(child.id, seen)) members.add(id);
    memberIds.set(regionId, members);
    return members;
  };

  const objectsByMemberIds = new Map<string, Set<typeof graph.objects>>();
  const summaries = new Map<string, RegionSummary>();
  for (const region of graph.regions) {
    const members = collect(region.id);
    let objects = objectsByMemberIds.get(region.id);
    if (!objects) {
      objects = new Set(graph.objects.filter((object) => members.has(object.id)));
      objectsByMemberIds.set(region.id, objects);
    }
    const typeCounts = new Map<string, number>();
    let attentionCount = 0;
    for (const object of objects) {
      typeCounts.set(object.objectType, (typeCounts.get(object.objectType) ?? 0) + 1);
      if (object.state.severity === "attention" || object.state.severity === "critical") attentionCount += 1;
    }
    const keyObjectNames = [...objects]
      .sort((left, right) => right.importance.score - left.importance.score || left.name.localeCompare(right.name))
      .slice(0, 3)
      .map((object) => object.name);
    let internalRelationships = 0;
    let crossingRelationships = 0;
    for (const relationship of graph.relationships) {
      const sourceInside = members.has(relationship.sourceObjectId);
      const targetInside = members.has(relationship.targetObjectId);
      if (sourceInside && targetInside) internalRelationships += 1;
      else if (sourceInside !== targetInside) crossingRelationships += 1;
    }
    summaries.set(region.id, {
      objectCount: objects.size,
      typeCounts: [...typeCounts.entries()]
        .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
        .map(([type, count]) => ({ type, count })),
      attentionCount,
      keyObjectNames,
      internalRelationships,
      crossingRelationships,
    });
  }
  return summaries;
}

