"use client";

import type { CSSProperties } from "react";
import type { Node, NodeProps } from "@xyflow/react";
import { readableLabelScale } from "./interaction";
import type { RegionNodeData } from "./types";

export type ArchitectureRegionNode = Node<RegionNodeData, "region">;

const TYPE_COPY: Record<string, string> = {
  service: "Service",
  agent: "Agent",
  storage: "Storage",
  external: "External",
};

export default function RegionNode({ data }: NodeProps<ArchitectureRegionNode>) {
  const { region, emphasis, zoomLevel, zoom, objectCount, childRegionCount, depth, summary } = data;
  const labelScale = readableLabelScale(zoom, 13, undefined, 2.8);
  const composition = summary.typeCounts.map(({ type, count }) => `${count} ${TYPE_COPY[type] ?? type}`).join(" · ");
  return (
    <section
      aria-label={`Region ${region.name}，${summary.objectCount} objects`}
      className={`canvas-region depth-${Math.min(depth, 3)} emphasis-${emphasis} zoom-${zoomLevel}`}
      style={{ "--label-scale": labelScale } as CSSProperties}
    >
      <header>
        <span>Region</span>
        <strong>{region.name}</strong>
        <small>
          {zoomLevel === "landscape" ? `${summary.objectCount} objects` : `${objectCount} objects${childRegionCount > 0 ? ` · ${childRegionCount} regions` : ""}`}
        </small>
      </header>
      <div className="region-summary" aria-hidden={zoomLevel === "landscape" ? undefined : undefined}>
        {composition && <p className="region-composition">{composition}</p>}
        {summary.attentionCount > 0 && <p className="region-attention">{summary.attentionCount} 待证据 / attention</p>}
        {zoomLevel === "landscape" && summary.keyObjectNames.length > 0 && (
          <p className="region-key-objects">关键 {summary.keyObjectNames.join(" · ")}</p>
        )}
        {summary.crossingRelationships > 0 && zoomLevel === "landscape" && (
          <p className="region-crossing">{summary.crossingRelationships} 条跨 Region 关系</p>
        )}
      </div>
    </section>
  );
}

