  onSelect,
}: {
  corridor: TraceCorridor;
  selectedObjectId: string | null;
  onSelect: (selection: CanvasSelection) => void;
}) {
  const transitionByTarget = new Map(corridor.transitions.map((t) => [`${t.fromStepId}->${t.toStepId}`, t]));
  const steps = corridor.steps;
  return (
    <aside className="trace-corridor" aria-label={`Trace corridor ${corridor.flow.name}`}>
      <header className="trace-corridor-heading">
        <small>Trace corridor</small>
        <strong>{corridor.flow.name}</strong>
        <span>{String(corridor.flow.metadata.trigger ?? "")} → {String(corridor.flow.metadata.outcome ?? "")}</span>
      </header>
      <ol className="trace-corridor-rail">
        {steps.map((entry, index) => {
          const next = steps[index + 1];
          const transition = next ? corridor.transitions.find((t) => t.fromStepId === entry.step.id && t.toStepId === next.step.id) : undefined;
          return (
            <li key={entry.step.id} className={entry.step.objectId === selectedObjectId ? "current" : ""}>
