// The opening camera is an architecture-density view, never a thumbnail of
// the whole map: the zoom floor is respected and content may overflow.
useEffect(() => {
  const layoutIdentity = layout ? `${storageKey}:${layout.fingerprint}` : "";
  if (!layout || !layoutIdentity || fittedLayoutRef.current === layoutIdentity) return;
  fittedLayoutRef.current = layoutIdentity;
  const timer = window.setTimeout(() => {
    const instance = instanceRef.current;
    const surface = surfaceRef.current;
    if (!instance || !surface) return;
    const rect = surface.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return;
    const bounds = topLevelRegionBounds(layout);
    if (!bounds) return;
    instance.setViewport(defaultViewport(bounds, { width: rect.width, height: rect.height }, {
      focus: primaryRegionFocus(graph, layout),
    }));
