.trace-corridor-rail > li > button { align-items: center; background: rgba(255,255,255,.02); border: 1px solid var(--map-line); color: var(--map-text); display: flex; gap: 8px; min-height: 46px; padding: 5px 9px; text-align: left; }
.trace-corridor-rail > li > button:hover { border-color: rgba(155,210,193,.35); }
.trace-corridor-rail > li.current > button { border-color: rgba(155,210,193,.6); background: rgba(155,210,193,.07); }
