async () => {
  const select = document.querySelector('select[aria-label="Stress fixture"]');
  select.value = "complex";
  select.dispatchEvent(new Event("change", { bubbles: true }));
  await new Promise((resolve) => setTimeout(resolve, 2400));
  const traceButton = [...document.querySelectorAll(".canvas-modes button")].find((button) => button.textContent.includes("Trace"));
  traceButton.click();
  await new Promise((resolve) => setTimeout(resolve, 250));
  document.querySelector(".flow-lens-list button").click();
  await new Promise((resolve) => setTimeout(resolve, 1500));
  const rail = document.querySelector(".trace-corridor-rail");
  const state1 = {
    zoom: document.querySelector(".react-flow__viewport").style.transform,
    railOverflow: Math.round(rail.scrollWidth - rail.clientWidth),
    corridorHeight: Math.round(document.querySelector(".trace-corridor").getBoundingClientRect().height),
    flowBadges: document.querySelectorAll(".object-flow-steps").length,
    activeEdges: document.querySelectorAll(".relationship-edge.emphasis-active").length,
  };
  document.querySelectorAll(".trace-corridor-rail li")[7].querySelector("button").click();
  await new Promise((resolve) => setTimeout(resolve, 900));
  const surface = document.querySelector(".canvas-flow-surface").getBoundingClientRect();
  const centered = [...document.querySelectorAll(".object-flow-steps")].map((badge) => badge.closest(".react-flow__node").getBoundingClientRect());
  const lastStep = centered[centered.length - 1];
  return {
    state1,
    afterLastStepClick: {
      zoom: document.querySelector(".react-flow__viewport").style.transform,
      visibleBadges: centered.length,
      lastBadgeCenter: lastStep ? { x: Math.round(lastStep.x + lastStep.width / 2 - surface.x), y: Math.round(lastStep.y + lastStep.height / 2 - surface.y) } : null,
      inspectorHeading: document.querySelector(".canvas-inspector .inspector-heading strong")?.textContent,
    },
  };
}

