  const label = [...document.querySelectorAll(".react-flow__node .object-label")].find((element) => element.getBoundingClientRect().width > 0);
  const labelRect = label.getBoundingClientRect();
  const regionName = [...document.querySelectorAll(".react-flow__node-region header strong")].find((element) => element.getBoundingClientRect().width > 0);
  const regionRect = regionName.getBoundingClientRect();
  return {
    zoom,
    zoomLabel: document.querySelector(".canvas-statusbar span")?.textContent,
    visibleSummaries: visibleSummaries.slice(0, 6),
    objectLabelGlyphPx: Math.round(zoom * 15 * (getComputedStyle(label).getPropertyValue("--label-scale") ? Number(getComputedStyle(label.closest(".object-node").style.getPropertyValue("--label-scale")) : 1) * 10)) / 10,
    objectLabelHeightPx: Math.round(labelRect.height * 10) / 10,
    regionNameHeightPx: Math.round(regionRect.height * 10) / 10,
  };
}

async () => {
  const select = document.querySelector('select[aria-label="Stress fixture"]');
  select.value = "medium";
  select.dispatchEvent(new Event("change", { bubbles: true }));
  await new Promise((resolve) => setTimeout(resolve, 2200));
  const viewport = document.querySelector(".react-flow__viewport");
  const zoom = Number(viewport.style.transform.match(/scale\(([\d.]+)\)/)?.[1] ?? 1);
  const visibleSummaries = [...document.querySelectorAll(".canvas-region .region-summary p")]
    .filter((p) => p.getBoundingClientRect().width > 0)
    .map((p) => p.textContent.trim());
  const label = [...document.querySelectorAll(".react-flow__node .object-label")].find((element) => element.getBoundingClientRect().width > 0);
  const node = label.closest(".object-node");
  const labelScale = Number(node.style.getPropertyValue("--label-scale") || 1);
  const regionName = [...document.querySelectorAll(".react-flow__node-region header strong")].find((element) => element.getBoundingClientRect().width > 0);
  return {
    zoom,
    zoomLabel: document.querySelector(".canvas-statusbar span")?.textContent,
    visibleSummaries: visibleSummaries.slice(0, 6),
    objectLabelEffectivePx: Math.round(zoom * 15 * labelScale * 100) / 100,
    objectLabelBoxPx: Math.round(label.getBoundingClientRect().height * 10) / 10,
    regionNameBoxPx: Math.round(regionName.getBoundingClientRect().height * 10) / 10,
  };
}

