  const surface = document.querySelector(".canvas-flow-surface").getBoundingClientRect();
  for (const tag of document.querySelectorAll(".verify-target")) tag.classList.remove("verify-target");
  const candidates = [...document.querySelectorAll(".canvas-region .region-summary")]
    .concat([...document.querySelectorAll(".canvas-region > header")])
    .filter((element) => {
      const rect = element.getBoundingClientRect();
      return rect.width > 0 && rect.bottom > surface.top + 20 && rect.top < surface.bottom - 20 && rect.right > surface.left + 20 && rect.left < surface.right - 20;
    });
  if (candidates.length === 0) return { found: 0 };
  const target = candidates[0];
  target.classList.add("verify-target");
  return {
    found: candidates.length,
    tagged: target.className,
    rect: target.getBoundingClientRect().toJSON(),
    text: target.textContent.trim().slice(0, 120),
  };
}

