async () => {
  const select = document.querySelector('select[aria-label="Stress fixture"]');
  select.value = "medium";
  select.dispatchEvent(new Event("change", { bubbles: true }));
  await new Promise((resolve) => setTimeout(resolve, 2200));
  const surface = document.querySelector(".canvas-flow-surface").getBoundingClientRect();
  const onscreen = (element) => {
    const rect = element.getBoundingClientRect();
    return rect.width > 0 && rect.bottom > surface.top + 10 && rect.top < surface.bottom - 10 && rect.right > surface.left + 10 && rect.left < surface.right - 10;
  };
  const headers = [...document.querySelectorAll(".react-flow__node-region > header")].filter(onscreen).map((header) => header.textContent.trim());
  const summaries = [...document.querySelectorAll(".canvas-region .region-summary")].filter(onscreen).map((summary) => summary.textContent.trim().slice(0, 60));
  const objects = [...document.querySelectorAll(".react-flow__node-object")].filter(onscreen).length;
  return {
    zoom: document.querySelector(".react-flow__viewport").style.transform,
    zoomLabel: document.querySelector(".canvas-statusbar span")?.textContent,
    onscreenRegionHeaders: headers,
    onscreenRegionSummaries: summaries,
    onscreenObjects: objects,
  };
}

