async () => {
  const pane = document.querySelector(".react-flow__pane");
  const drag = (fromX, fromY, toX, toY) => {
    pane.dispatchEvent(new MouseEvent("mousedown", { clientX: fromX, clientY: fromY, bubbles: true }));
    for (let step = 1; step <= 6; step += 1) {
      pane.dispatchEvent(new MouseEvent("mousemove", { clientX: fromX + (toX - fromX) * step / 6, clientY: fromY + (toY - fromY) * step / 6, bubbles: true }));
    }
    pane.dispatchEvent(new MouseEvent("mouseup", { clientX: toX, clientY: toY, bubbles: true }));
  };
  drag(700, 400, 500, 320);
  await new Promise((resolve) => setTimeout(resolve, 700));
  return {
    transform: document.querySelector(".react-flow__viewport").style.transform,
    mountedObjects: document.querySelectorAll(".react-flow__node-object").length,
  };
}

