  if (!layout) return { cached: false };
  const transform = document.querySelector(".react-flow__viewport").style.transform;
  const match = transform.match(/translate\(([-\d.]+)px,\s*([-\d.]+)px\)\s*scale\(([\d.]+)\)/);
  const tx = Number(match[1]), ty = Number(match[2]), k = Number(match[3]);
  const pane = { x: (0 - tx) / k, y: (0 - ty) / k, width: 1544 / k, height: 776 / k };
