const subtreeObjectCount = (regionId: string, seen = new Set<string>()): number => {
  if (seen.has(regionId)) return 0;
  seen.add(regionId);
  let total = objectsByRegion.get(regionId)?.length ?? 0;
  for (const child of childRegions.get(regionId) ?? []) total += subtreeObjectCount(child.id, seen);
  return total;
};

const objectNodesOf = (regionId: string) => [...(objectsByRegion.get(regionId) ?? [])]
  .sort((left, right) => (objectOrder.get(left.id) ?? 0) - (objectOrder.get(right.id) ?? 0) || left.id.localeCompare(right.id))
  .map<ElkNode>((object) => {
    const size = objectSize(object.name, object.summary);
    return {
      id: object.id,
      width: size.width,
      height: size.height,
      ports: (portsByObject.get(object.id) ?? []).sort((left, right) => left.side.localeCompare(right.side) || left.order - right.order).map(asElkPort),
      layoutOptions: {
        "elk.portConstraints": "FIXED_ORDER",
        "elk.layered.priority.direction": String(Math.round(object.importance.score)),
      },
    };
  });

const buildRegion = (region: SemanticRegion): ElkNode => {
  const depth = regionDepth(region, regionById);
  const nestedRegions = [...(childRegions.get(region.id) ?? [])]
    .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id));
  const objects = objectNodesOf(region.id);
  const composable = nestedRegions.length >= 3 && objects.length === 0;
  const children: ElkNode[] = composable
    ? composeRegionRows(nestedRegions, (child) => subtreeObjectCount(child.id)).map((row, rowIndex) => ({
      id: `${region.id}:row:${rowIndex}`,
      children: row.map(buildRegion),
      layoutOptions: rowOptions(),
    }))
    : [...nestedRegions.map(buildRegion), ...objects];
  return {
    id: region.id,
    children,
    layoutOptions: composable
      ? { ...regionOptions(orientation, depth), "elk.direction": "DOWN" }
      : regionOptions(orientation, depth),
  };
};

const rootRegions = [...(childRegions.get(null) ?? [])]

