const buildRegion = (region: SemanticRegion): ElkNode => {
  const depth = regionDepth(region, regionById);
  const nestedRegions = [...(childRegions.get(region.id) ?? [])]
    .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id));
  const objects = objectNodesOf(region.id);
  const composable = nestedRegions.length >= 3 && objects.length === 0;
  const children: ElkNode[] = composable
    ? composeRegionRows(nestedRegions, (child) => subtreeObjectCount(child.id)).map((row, rowIndex) => ({
      id: `${region.id}:row:${rowIndex}`,
      children: row.map(buildRegion),
      layoutOptions: rowOptions(),
    }))
    : [...nestedRegions.map(buildRegion), ...objects];
  return {
    id: region.id,
    children,
    layoutOptions: composable
      ? { ...regionOptions(orientation, depth), "elk.direction": "DOWN" }
      : regionOptions(orientation, depth),
  };
};

const rootRegions = [...(childRegions.get(null) ?? [])]
