const rootComposable = rootRegions.length >= 3;
const rootChildren: ElkNode[] = rootComposable
  ? composeRegionRows(rootRegions, (region) => subtreeObjectCount(region.id)).map((row, rowIndex) => ({
    id: `${graph.id}:row:${rowIndex}`,
    children: row.map(buildRegion),
    layoutOptions: rowOptions(),
  }))
