  const finished = typeof performance === "undefined" ? Date.now() : performance.now();

  // ELK layered keeps one direction for a whole INCLUDE_CHILDREN run, so the
  // top of the map would read as one long horizontal strip. Pure Region
  // levels are composed into rows here; objects keep their ELK positions
  // relative to their composition unit, and relationships crossing units are
  // left to the SmartEdge obstacle-avoiding render fallback.
  const COMPOSITION_GAP = 64;
  const objectUnitKeys = new Map<string, string[]>();
  const objectDeltas = new Map<string, { dx: number; dy: number }>();
  const addDelta = (delta: { dx: number; dy: number } | undefined, addition: { dx: number; dy: number }) =>
    ({ dx: (delta?.dx ?? 0) + addition.dx, dy: (delta?.dy ?? 0) + addition.dy });

  const translateSubtree = (regionId: string, delta: { dx: number; dy: number }, unitId: string) => {
    const regionRect = regionRects[regionId];
    if (regionRect) regionRects[regionId] = { ...regionRect, x: regionRect.x + delta.dx, y: regionRect.y + delta.dy };
    for (const object of objectsByRegion.get(regionId) ?? []) {
      const rect = objectRects[object.id];
      if (rect) objectRects[object.id] = { ...rect, x: rect.x + delta.dx, y: rect.y + delta.dy };
      objectDeltas.set(object.id, addDelta(objectDeltas.get(object.id), delta));
      objectUnitKeys.set(object.id, [...(objectUnitKeys.get(object.id) ?? []), unitId]);
    }
    for (const child of childRegions.get(regionId) ?? []) translateSubtree(child.id, delta, unitId);
  };

  const packLevel = (parentId: string | null) => {
    const children = [...(childRegions.get(parentId) ?? [])]
      .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id));
    for (const child of children) packLevel(child.id);

    const pureLevel = parentId === null || (objectsByRegion.get(parentId)?.length ?? 0) === 0;
    if (!pureLevel || children.length < 3) return;
    const rows = composeRegionRows(children, (child) => regionRects[child.id]?.width ?? 0);
    const placed = [...children].filter((child) => regionRects[child.id]);
    if (placed.length === 0) return;
    const originX = Math.min(...placed.map((child) => regionRects[child.id]!.x));
    const originY = Math.min(...placed.map((child) => regionRects[child.id]!.y));
    let rowY = originY;
    for (const row of rows) {
      let x = originX;
      let rowHeight = 0;
      for (const child of row) {
        const rect = regionRects[child.id];
        if (!rect) continue;
        translateSubtree(child.id, { dx: x - rect.x, dy: rowY - rect.y }, child.id);
        x += rect.width + COMPOSITION_GAP;
        rowHeight = Math.max(rowHeight, rect.height);
      }
      rowY += rowHeight + COMPOSITION_GAP;
    }

    if (parentId !== null) {
      const childRects = children.map((child) => regionRects[child.id]).filter((rect): rect is RegionLayoutRect => Boolean(rect));
      if (childRects.length > 0) {
        const depth = regionDepth(regionById.get(parentId)!, regionById);
        const minX = Math.min(...childRects.map((rect) => rect.x));
        const minY = Math.min(...childRects.map((rect) => rect.y));
        const maxX = Math.max(...childRects.map((rect) => rect.x + rect.width));
        const maxY = Math.max(...childRects.map((rect) => rect.y + rect.height));
        const topPad = depth === 0 ? 100 : 64;
        regionRects[parentId] = {
          ...regionRects[parentId]!,
          x: minX - 27,
          y: minY - topPad,
          width: maxX - minX + 53,
          height: maxY - minY + 53,
        };
      }
    }
  };
  packLevel(null);

  const compositionUnits: Record<string, string> = {};
  for (const object of graph.objects) {
    compositionUnits[object.id] = (objectUnitKeys.get(object.id) ?? []).join("|") || object.regionId;
  }
  for (const relationship of graph.relationships) {
    const route = relationshipRoutes[relationship.id];
    if (!route) continue;
    const sourceUnit = compositionUnits[relationship.sourceObjectId];
    const targetUnit = compositionUnits[relationship.targetObjectId];
    if (sourceUnit !== targetUnit) {
      delete relationshipRoutes[relationship.id];
      continue;
    }
    const delta = objectDeltas.get(relationship.sourceObjectId) ?? { dx: 0, dy: 0 };
    if (delta.dx === 0 && delta.dy === 0) continue;
    relationshipRoutes[relationship.id] = {
      ...route,
      points: route.points.map((point) => ({ x: point.x + delta.dx, y: point.y + delta.dy })),
      labelPoint: route.labelPoint ? { x: route.labelPoint.x + delta.dx, y: route.labelPoint.y + delta.dy } : undefined,
    };
  }

  const composedRects = [...Object.values(objectRects), ...Object.values(regionRects)];
  const composedWidth = composedRects.length > 0
    ? Math.max(...composedRects.map((rect) => rect.x + rect.width)) + 42
    : (output.width ?? 0);
  const composedHeight = composedRects.length > 0
    ? Math.max(...composedRects.map((rect) => rect.y + rect.height)) + 42
    : (output.height ?? 0);

  const result: CanvasLayout = {
    graphId: graph.id,
    fingerprint,
    orientation,
    width: Math.max(output.width ?? 0, composedWidth),
    height: Math.max(output.height ?? 0, composedHeight),
    durationMs: Math.round((finished - started) * 100) / 100,
    objectRects,
    regionRects,
    relationshipRoutes,
    compositionUnits,
  };
  return options.previousLayout ? stabilizeIncrementalLayout(graph, options.previousLayout, result) : result;
}

