+// Pure Region levels compose two-dimensionally after ELK: rows of Regions
+// stacked vertically, so the top of the map reads as an area instead of one
+// long horizontal strip. Object-level Flow layout inside leaf Regions keeps
+// its directed ELK orientation and routes.
+function composeRegionRows<T>(children: T[], weightOf: (child: T) => number): T[][] {
+  const count = children.length;
+  if (count < 3) return [children];
+  const rowCount = Math.max(2, Math.min(count, Math.ceil(Math.sqrt(count / 2))));
+  const targetWeight = children.reduce((sum, child) => sum + weightOf(child), 0) / rowCount;
+  const rows: T[][] = [];
+  let current: T[] = [];
+  let currentWeight = 0;
+  for (let index = 0; index < count; index += 1) {
+    current.push(children[index]);
+    currentWeight += weightOf(children[index]);
+    const rowsLeftAfterClose = rowCount - rows.length - 1;
+    const childrenLeftAfterClose = count - index - 1;
+    if (rowsLeftAfterClose > 0 && childrenLeftAfterClose >= rowsLeftAfterClose && currentWeight >= targetWeight * 0.6) {
+      rows.push(current);
+      current = [];
+      currentWeight = 0;
+    }
+  }
+  if (current.length > 0) rows.push(current);
+  return rows;
