  });
  return {
    zoom: document.querySelector(".react-flow__viewport").style.transform,
    zoomLabel: document.querySelector(".canvas-statusbar span")?.textContent,
    railOverflow: Math.round(document.querySelector(".trace-corridor-rail").scrollWidth - document.querySelector(".trace-corridor-rail").clientWidth),
    stepCount: document.querySelectorAll(".trace-corridor-rail li").length,
    currentChip: document.querySelector(".trace-corridor-rail li.current strong")?.textContent,
    badgesOnscreen: badges.filter((badge) => badge.x > 0 && badge.x < surface.width && badge.y > 0 && badge.y < surface.height),
    surfaceCenter: { x: Math.round(surface.width / 2), y: Math.round(surface.height / 2) },
    activeEdges: document.querySelectorAll(".relationship-edge.emphasis-active").length,
    mutedEdges: document.querySelectorAll(".relationship-edge.emphasis-muted").length,
  };
}

